CREATE TABLE IF NOT EXISTS "playlist" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "serverURL" TEXT NOT NULL, "username" TEXT NOT NULL, "password" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT '2026-11-07 01:02:32.620', "filterAdultContent" BOOLEAN NOT NULL DEFAULT 0, "type" TEXT NOT NULL DEFAULT 'xtream', "m3uEpgURL" TEXT);
