CREATE TABLE IF NOT EXISTS "vodStream" ("streamId" INTEGER NOT NULL, "name" TEXT NOT NULL, "streamIcon" TEXT, "categoryId" TEXT, "rating" TEXT, "containerExtension" TEXT, "sortIndex" INTEGER NOT NULL DEFAULT 0, "playlistId" TEXT NOT NULL REFERENCES "playlist"("id") ON DELETE CASCADE, "director" TEXT, "cast" TEXT, "plot" TEXT, "genre" TEXT, "releaseDate" TEXT, "rating5Based" DOUBLE, "backdropPath" TEXT, "youtubeTrailer" TEXT, "duration" TEXT, "tmdbId" TEXT, "kinopoiskURL" TEXT, "metadataLoaded" BOOLEAN NOT NULL DEFAULT 0, "added" TEXT, PRIMARY KEY ("streamId", "playlistId"));
