CREATE TABLE IF NOT EXISTS "series" ("seriesId" INTEGER NOT NULL, "name" TEXT NOT NULL, "cover" TEXT, "plot" TEXT, "genre" TEXT, "rating" TEXT, "categoryId" TEXT, "sortIndex" INTEGER NOT NULL DEFAULT 0, "seasonsLoaded" BOOLEAN NOT NULL DEFAULT 0, "playlistId" TEXT NOT NULL REFERENCES "playlist"("id") ON DELETE CASCADE, "cast" TEXT, "director" TEXT, "releaseDate" TEXT, "lastModified" TEXT, "rating5Based" DOUBLE, "backdropPath" TEXT, "youtubeTrailer" TEXT, "episodeRunTime" TEXT, PRIMARY KEY ("seriesId", "playlistId"));
CREATE TABLE IF NOT EXISTS "season" ("id" TEXT PRIMARY KEY, "seasonNumber" INTEGER NOT NULL, "name" TEXT, "overview" TEXT, "cover" TEXT, "seriesId" INTEGER NOT NULL, "playlistId" TEXT NOT NULL, "airDate" TEXT, "episodeCount" INTEGER, "voteAverage" DOUBLE, FOREIGN KEY ("seriesId", "playlistId") REFERENCES "series"("seriesId", "playlistId") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "episode" ("id" TEXT PRIMARY KEY, "episodeId" TEXT, "episodeNum" INTEGER, "title" TEXT, "containerExtension" TEXT, "info" TEXT, "cover" TEXT, "duration" TEXT, "rating" TEXT, "seasonId" TEXT NOT NULL REFERENCES "season"("id") ON DELETE CASCADE);
